def threshold_with_hangover(db, threshold, hangover):
    out, left = [], 0
    for e in db:
        if e > threshold:
            out.append(1)
            left = hangover
        elif left > 0:
            out.append(1)
            left -= 1
        else:
            out.append(0)
    return out
